/// Build a resolved token table for a built-in theme.
pub fn resolved_table(name: &str) -> Option<HashMap<String, String>> {
    let mut table: HashMap<String, String> = BASE_TOKENS.iter().map(|(k, v)| (k.to_string(), v.to_string())).collect();
    let overrides = THEME_OVERRIDES.iter().find(|(n, _)| *n == name)?.1;
    for (k, v) in overrides {
        table.insert(k.to_string(), v.to_string());
    }
    Some(resolve_aliases(table))
}

fn resolve_aliases(mut raw: HashMap<String, String>) -> HashMap<String, String> {
    let keys: Vec<String> = raw.keys().cloned().collect();
    for key in keys {
        let mut seen = std::collections::HashSet::new();
        let mut cur = raw[&key].clone();
        while cur.starts_with('@') {
            let alias = &cur[1..];
            if !seen.insert(alias.to_string()) { break; }
            cur = raw.get(alias).cloned().unwrap_or(cur);
        }
        raw.insert(key, cur);
    }
    raw
}
